) AS (
  VALUES 
    (111::BIGINT, 'Merece calificación perfecta, es un excelente profesor y una gran persona. Los cursos de ciencias sociales por sí solos son aburridos pero con él son muy entretenidos. El curso se pasa asegurado, y el profe siempre esta para resolver cualquier duda, es muy comprensivo y le gusta hablar con otros.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, '99813477432ba3e44afad213316e424204836038e9e3c169d125c94ebff362da'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El profe es muy buena persona, sabe que su clase es aburrida pq lo es pero siempre trata de hacer bromas o hacerlo mas ameno para que la pases bien, califica super suave no hay que hacer casi nd entonces si puedes matricular con el 100% recomendado un 10 de profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'f07b935fa2e7735c1e0ee405b55515ba24aa554775200f6059dc8ad95675d4d5'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El mae es increíble, sabe que su clase es aburrida entonces prefiere hacer bromas intelectuales y chistes de lo que explica. Las evaluaciones son super fáciles y claras. Le gusta trabajar en grupos. Por cualquier cosa, pasa lista al principio de la clase, para que lleguen temprano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-13T00:00:00+00:00'::TIMESTAMPTZ, '36777c4aca0fe2f351d1bec0d1c6da8fef0c968b752ea603626b8c7bbfe829af'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Este profe es demasiado genial, matriculen con él si tienen la oportunidad. Él no hace quizzes, y los exámenes son fáciles. La materia como tal es aburrida, pero aún así el profe logra hacer un ambiente agradable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '0a466cc7a4fa2ef768b2d378221a994fc5d081c2d9857277b9e357c83e9b6442'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El profe es genial, las clases siempre son muy divertidas, y los trabajos no son muy complicados, y no hace quizzes. En general el profe explica genial, valora el buen trabajo y la participación, y el curso se hace un highlight de la semana cada clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ef8ecbd788bc21a7a9ed74506482b770008a191eab53ba74461a4a8510f74d29'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El mejor profe, aunque la materia en si es aburrida, hace que uno se interese por los temas, ademas de que es muy comico y es flexible si uno se pasa con las fechas de entrega. Si piensa matricular con el no lo dude'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '4283466e404bd14dccfb0664b95c2e6d7784ffa8fb0e467ed99eac639cd17f5f'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Una materia tan aburrida no merece a un profesor tan divertido y comico como el. Vaya preparado con la lectura asignada y puede llegar a disfrutar de un intercambio de ideas. Es muy sencillo pasar si le dedica el tiempo necesario para los examenes y audiovisuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7d650c52b7140d14fa3792446bf78c8e16b3236b426236ba395b4545a4499199'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'el mejor profe para llevar el curso, ni se la piense dos veces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '065273b6df40b3562020245e1a925652da1ea9b720239041918f44e1a0fc7968'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Excelente profe que le toca dar una materia muy aburrida, califica suave, es comprensivo y permite que el curso sea muy fácil. Entabla buenas relaciones con los estudiantes (en mi caso, nos compró pizza)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, '9b6de30f65f0c0b68c0fa457b83330c666c3bd8cb8466645cc75de945aa1a228'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Muy buen profe, bastante amable y muy flexible con las entregas. Él entiende que a veces uno tiene mucha carga por otros cursos entonces siempre está dispuesto a ayudarlo a uno, incluso dando más tiempo para entregar trabajos. Recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a9b32677a979b66800622ae948d4861beea5380f8047b74e69f87f8cc5a296ff'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2026-05-13T00:00:00+00:00'::TIMESTAMPTZ, '10984dc59126c7c1832a64fc2d4d0b270d62320ea1984586b4ee15f14ed8c802'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Muy buen profesor, te ayuda mucho y explica muy bien, la materia la hace entretenida.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2026-03-21T00:00:00+00:00'::TIMESTAMPTZ, '54f9a83d6290843091a6a28a33c57bb3e785afc61fa4f4cfe158881927648d12'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Muy buen profe, las clases son entretenidas y realmente se aprende algo. Pasa lista al inicio, se realizan trabajos escritos sencillos y debates grupales. Es muy compresivo con cualquier dificultad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-02-04T00:00:00+00:00'::TIMESTAMPTZ, '9ceed40f72b3e2e2d4ee4a5455d719ea6f76249afc64eca950622f7d98f0f51e'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Profesor excelente, materia aburrida pero él hace la clase entretenida, excelente persona y califica super suave (100 asegurado). El mejor profe de ciencias sociales sin duda alguna.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '18b6662c3a9391a06334b8a28e93e067812cbdac012619baeb95ca8d0378ca0f'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Unos de los filósofos mas emblemáticos del Tec que ademas ayuda mucho y las clases se vuelven inspiraciones y ensimesmado, aveces hace preguntas antológicas pero da muy buenas clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2025-12-13T00:00:00+00:00'::TIMESTAMPTZ, '99924292f6694065a35fb61d16d3db693f58201f052e28f16ae225f7d3a5c40f'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Uno de los más grandes filósofos de nuestra época. Es de esas pocas clases que esperaba a que fuera ese día por lo interesantes que llegaban a ser. El profe le importa más el pensamiento crítico que el conocimiento de un tema por lo que las clases se vuelven muy pensativas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, '965b1f81822b3d8cbe8cb6c291a959240058fdc0ac963d2bd0c71506cfce2777'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Increíble profe, explica muy bien y las clases no se sienten tan largas, suele hacer las clases bastante dinámicas. La mayoría de trabajos son grupales y califica suave. Muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '4a5885d168f2ff456c21a701f5712cbb304884c26d9f9f4588faa1e407abb126'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Al inicio no me interesaba nada el curso pero el profe hizo que me gustara ir a sus clases, muy buena gente, es vacilón, hace la clase muy entretenida, Tenes que participar bastante, pero super ez si entregas los trabajos fijo tienes 100 o cercano, lo recomiendo bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '12dd397ec3a4f3ca821af7e562ca018e74732db15748803558ea176483d898f2'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Es increíble como profe, hace que tengas interés en la clase. Los debates son súper divertidos y en general el profe es muy divertido. Si deja varios trabajos, pero no son tan complicados, y no califica duro. Yo lo recomiendo full.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchos proyectos grupales']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '4e453e7866f3f04dd8e166efbd2c36a5d0322d02659d1d917fdb13e29401e8c6'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Es un excelente profesor lo mejor de ciencias sociales, deja lecturas casi todas las semanas pero fuera de eso califica justo, hace chistes y es muy comico'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2025-11-14T00:00:00+00:00'::TIMESTAMPTZ, '26c179d797a90cecd0ad60e2dacae1576b823e49a23da8c75a812f9cecdfc0a8'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Muy buen profesor, siempre apoya al estudiante y suele hacer muchos chistes. Si se le pide más tiempo para algo, lo da, son clases muy llevaderas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'La participación importa']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'c5cb7cf008b043e6191c45a4f7a2ac45c5d8538f43079ebc15d1126c3af6dbd6'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'df8bb4607d704759ac51262a621afb364b047e7ec940eff96443ec09111f8e52'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros']::TEXT[], '2025-09-21T00:00:00+00:00'::TIMESTAMPTZ, 'c67baa84fb67e6a0436a9d4c096989a4c7ab598e7edc2e3261a5c839c876545c'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Demasiado buen profe, sabe que su materia no es la mas relevante entonces es flexible para que uno le ponga mas a lo verdaderamente demandante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-14T00:00:00+00:00'::TIMESTAMPTZ, '96aec9006523b16af846532f5f5c05e868d8f5da4da84b0536fe6297ae63ef62'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Una teja de persona y se nota que le interesa la materia. Además él es consciente que a muy poca gente le interesa la clase y la lleva por ser obligatoria entonces le da igual la gente que va y no participa. Manda a leer o ver mucho material pero al final con que 2 lo hayan visto él se monta la clas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-09T00:00:00+00:00'::TIMESTAMPTZ, '06693a6ce04e8ef2e025e190e3574bb7070150b6e48cce1174b2837dbaea25d2'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Gran profe y persona. Siempre intenta sacarle una sonrisa a los estudiantes y es muy cómico, los exámenes y reportes se pueden hacer en grupo y son sencillos. El mejor para intro al bostezo. Un 100 fácil con entregar todo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '91bb06112529a60227ba39d97588e2e0f2aba913f02d0b595ee1478a1b1aa81f'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El profe es una teja, califica muy muy suave, es comprensible al momento de las evaluaciones y puede posponer fechas de entrega. Hace la clase bastante comica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'ce316a5e2536f37a0a75a3e452a68cf98f07f771f812dfbd9f9462013846ab6f'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Simplemente el Goat Garro mejor profe de intro al boztezo super facil, Posdata: Garro asme un hijo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, '1485a2a25794abba825b642eb991fd7b8feda3e5ede41c4bfdd165a4b05402c3'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El mejor profe de ciencias sociales, recomendadísimo. Deja trabajos pero son muy sencillos y si tiene duda le va a ayudar. Además, es muy cómico y califica muy bien, repetiría otro curso con él sin pensarlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, '67df03a2b4ed4d090dafe1bb710d4207eccff06eb124fcda417e56f5da623e71'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'el profe es muy buena nota cualquier pregunta que usted le haga se la responde y también si usted tiene un problema para alguna entrega él le ayuda sin ningun problema. además hace que intro a la ciencia y tecnología no sea tan aburrida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2024-11-13T00:00:00+00:00'::TIMESTAMPTZ, '5880a9d9a2c1325c25840540551f181f13964e559c148ea771d47eb839416fee'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'c3a7a5970fd83c934f883ecd22159c82d3a5f5ccb358b3241a6a83289e4e226a'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El profe es muy buena nota, y las clases solo son aburridas si no se participa mucho, los trabajos escritos son sencillos pero si hay que dedicarles un buen rato, y las lecturas y videos que mandan si pueden ser bastante largos, pero igual con cumplir con los trabajos escritos se pasa sobrado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c6d010aea529f3f08d7563312226b9d59830bb4c362a5ecec5132dc756844387'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Un profe excelente, de verdad. Hace pocas entregas, que son muy fáciles. Si usted le pide ayuda, él hace lo posible por ayudarle y es super comprensivo. El curso en sí es aburrido, pero este profe hace la clase divertida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '3fb7f6a034afa8fcb43493c602c6e33737411bcec9f2f8acbec2136c7fd9b7c5'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Lo amo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '50fc6d8dfabaeea005d98aed947b3f7c2d92a0316c5dbafab357313054ff1176'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El profe es muy cómico, hace la clase entretenida y casi siempre saliamos 30min antes o más'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'ff78867ddef6a56941524ded461837ca40da683e170766c15e74997ad4ccdda4'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Exelente profe, le rezo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '1597f5f7875776a7d24457f48bb94731ec6ec11ebb10cc6754528d73e6336f94'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Los trabajos que deja son sencillos y se pueden hacer en grupos grandes, además califica super suave, el 100 es casi asegurado. Matricule sin pensar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'e24722274f1f77c4c9cce640dcb6eb5da35a449be5f46712a7c9cda43f912787'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Top profes del TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'd57f2ca52792cf4c8acb2346abeca8fd6b866fae5b9188617c35b608c6830b05'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Un profe súper buena nota. Se nota que disfruta enseñar el tema. Algunas clases fueron aburridas, pero en general fue entretenida y fácil de pasar gracias a sus trabajos, los cuales no requerían de lectura extensa como lo es con otros profes. Lleve con él y ya pasó el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'e87ad5cb71d31a6f8ae9089cfadc593bfa2f2f34b76ba561bada0393d4249786'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El profe es muy buena nota, pero le gusta hablar mucho que hace que las clases se hagan largas, deja trabajos medio largos que se hacen aburridos, pero, de ahí en fuera si usted le tiene interés se le hace una clase bonita, sino, no.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e03fece1864b2af58f35e36a24268304db82f157abc0080e0b5f711609c118dd'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El curso es muy bueno, el profe excelente, entretenido y cómico. No califica duro. Le gusta que participen en clase. Deja muchas lecturas y algunos videos, se deben hacer tareas o exámenes con base a ellas, pero son fáciles de hacer si le pone interés. Nos Invitó a Pizza al final del curso :).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '897d9a9e7c6f0338e9ec80126e481320bc1a17966767030d31be6aef6b032766'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El curso en sí es muy aburrido, pero con el profe se pasa entretenido. Si quiere pone atención, aunque le gusta que participen. Deja muchas lecturas y hay que hacer reportes sobre ellas, pero no son tan complicados (usen chatgpt). No califica duro e invitó pizza al final del curso (es genial lo tqm)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'a599d5120be97f3d40036a02c896d35e28c6bff17a2439e2173daef455a0e26e'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El curso es aburrido, pero el profesor trata de que no sea tan aburrido. Se pasa fácil, deja pocas lecturas y trabajos sencillos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'bdac7b49c00c603f9225e27c5a7609fa14250ae56a93088ffcd3b32a8680513f'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Las clases son aburridas, pero como profesor es calidad. Atiende consultas a toda hora. Siempre está de buen humor. El curso se pasa sencillamente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-10-14T00:00:00+00:00'::TIMESTAMPTZ, '6230e6dadfe657ab3b15b67b41f255a137d90c80d9882a142a638590886dc9ad'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El profesor logra hacer que la clase sea muy entretenida. Es muy amigable y siempre se asegura de que uno aprenda. Matriculen con él sin miedo, es el mejor para esta clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f36d7fce4ae1f9cc663baaa6344256449c0d12608c133be3e44cfc0a185531f3'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Un profe super buena gente, la clase a veces aburre pero es por la materia, no tanto por el profe. Muy comprensivo y dispuesto a ayudarlo a uno con más tiempo, y demás. Trata de hacer el curso más ameno y cómico'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '1e81a761ba114d2ed03ea0ae1165ffa199e2f6fb14edd46f522b0159feb29caa'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El profe es buena gente, se intenta llevar bien con sus estudiantes y las clases normalmente son entretenidas. Habla, y bastante. Algunas veces repite mucho las cosas, pero dejando eso por un lado, es buena gente, buen profe y vale la pena llevar un curso con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f175e224b025d26d1521990577e5687fbcefcf9ce81e24acc18064c43eb013ac'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Buen profe, intenta que sus clases no sean aburridas. Hace chistes, humilde y super amable. Los trabajos son muy faciles y en grupo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'bfd8d272e44568213e59cd58a1a920349dfcae0dbca4bb60fd40813fbef0771e'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El profe es lo mejor!!! Los trabajos son super fáciles, casi nunca pasó lista, el profe es muy buena gente entonces hace las clases llevaderas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-06T00:00:00+00:00'::TIMESTAMPTZ, '74bb0e5ea6743ed4d4f8c6cf3a907c1eb15b26f832cf79a3aa4ebf6f38c5684c'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor, muy amable y humilde, él es muy relajado y sus trabajos son realmente fáciles, pero son largos y algunos son en grupos, es un curso muy fácil de pasar con el, pero igualmente hay que dedicarle su tiempo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'f4cce8fcd6dfdb06abf3f0709443838b86e65149e6b67515e7825bf9813dc7c0'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Demasiado buena gente y hace la clase entretenida, hay muchos trabajillos pero nada del otro mundo. Es super comprensivo para dar mas chance en entrega de tareas. En resumen 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'cf66f6df1b0d44644856b11c5fc25ac5cecb863104f1cfd834ba9a30356375bf'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Como profe es muy tuanis y gracioso, ayuda bastanta para llevar este tipo de cursos que suelen ser aburridos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'e7a41f7ce8fa237670a9915485c70d9423d5bfa36beee5225ad19fe711b83b0c'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Como persona y profesor es excelente. Siempre pasa pidiendo la opinión de los estudiantes. Hay que leer algunas lecturas y ver películas o videos (son como tres máximo), ya que de ahí se hacen las tareas y los exámenes, por eso no dejar todo para lo último.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-08-27T00:00:00+00:00'::TIMESTAMPTZ, '5d4050cfbf06921712acd5cd172bca71fc806c5459cb74c1706183f1e8a37bfd'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Varias lecturas y se ven tres películas, pero yo casi no las lei y pase el curso con 95, es solo de tener un pensamiento crítico y participar en clase, en los exámenes le gusta tanto cantidad como calidad, da buena retroalimentación y es excelente como persona, muy comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '708519e240e3657473dfff0b7c110483e6379b16a3a513065d458b8595a26c92'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Las clases muy aburridas, se pasa súper fácil, muy desordenado da un cronograma y no lo cumple, sin ir a clases se pasa al suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '98016c4a1eabfa367a87f3ff187b62ca880a3ad060c831afa65438e6f0c9630b'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Muy buen profe, super relajado. En virtual no hacia falta ir a las clases. Evaluación super clara y con solo entregar los trabajos hechos pasa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '67adae0440a03ed03bcaa9f8080a99c11a6b2e274cae869b62cecad21080d0c6'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor, le encanta que uno participe pero no es de obligar a los alumnos, califica con reportes de documentales, películas o lecturas, todo lo que enseña es super chiva entonces no tenga miedo y matricule con él. Sus clases son muy entretenidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-06-19T00:00:00+00:00'::TIMESTAMPTZ, '95a0cea9851102583fecc9f257d3fd617a68912639a6baeb993611797b39008f'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Es un super profe, es fácil y se aprende bastante. Lo recomiendo al mil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, '0db14cbcb83c8697146de06468b97cee534c0d391fcb5990fd1458cec81df28d'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Es muy entretenida la clase, los trabajos audiovisuales son fáciles, deja un ensayo y da buenos temas y el proyecto grupal es lo mas complejo pero no se siente ya que el brinda consulta 24/7.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'abe2f5f87b638548dec902439ffa6cc676e8e6703c1d2fee8c50c0e08d283107'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Es el mejor profe de todo el TEC. Las evaluaciones son sencillas, reportes de audiovisuales que son muy entretenidos y fáciles de entender. Hay un proyecto final en grupo y califica suave. Muy recomendado para cualquier curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '335c319fd759792be6dc7e65b3a36605c240436187a75920e0363bef8240a2c0'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '99cc6c75596cc07aea8b77259933533e1e18dd4f10336fb4340af2b8aee64d1b'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El curso es muy fácil de pasar y el profe califica muy suave, a menos de que sea muy malo haciendo ensayos cortos, es 100 asegurado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '4c44d9d97caa9d4162920f7e49154683ae950fd51d0c3a791133b37e955c1bd3'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Es super buena nota, clases cortas y califica suave. Casi no deja trabajos y al final hay que hacer un proyecto en grupo. Le gusta que el estudiante entienda, se interese en los temas y participe. Super recomendado!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '20ed668ba845461d8beae857ea9db5e4c770fb63b15f174bcf6921e3497678e7'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor, explica muy bien, los exámenes son muy sencillos, siempre está dispuesto a ayudar y volver a explicar un tema si no quedó del todo claro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3d84a1fbdb38e9b3c9705d5bbdcd812ad92dfe49763f7ad9c78ffd573231fecf'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Es uno de los mejores profes o el mejor de ciencias sociales. Explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'd3a4c6b55ae4c06b112d1eeedad719a804198026fd70adb1795d90bddee086a3'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Excelente Profesor, las clases son muy claras y entretenidas. Se aprende mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'b0dbc2f70c10f9eeb91e657b55567344dfc7cdc5d4808cf16dc73a93dbf3302b'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'La clase es muy fácil, el profesor la hace entretenida y bastante dinámica. Hay mucho que leer (aunque yo no hice ninguna), los trabajos no son para nada complicados. Él es muy amable y cariñoso. Se pasa fácil y la evaluación es sencilla.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases largas']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a18a65b2cd91b87d2a4e527dbe51f0c69c67f37b76f61a28a7b2aa2c618261ea'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Muy buen profesor!! Explica todos los temas de una manera entretenida y sencilla de aprender. Los trabajos no son largos y si participa en las clases y lee las lecturas asignadas no se le hacen dificiles. El está dispuesto a ayudar a sus estudiantes. No dude en matricular con él! Super recomendado!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '1b00747b2524395f84f50ebe652c93dd9d72431017443c3107c841c7a817f856'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e7eb6ca78e837dcbb7b427727daa56270cb473c1168aeb2be97e516c332b86bd'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Excelente profe, muchos hablan mal de este curso sin embargo él lo hace totalmente entretenido, no deja muchos trabajos y brinda mucha ayuda. Es una excelente persona que se gana a cualquiera, excelente profesor tiene mucha vocación y se nota que le gusta lo que hace. Si se puede matricule con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '13b4546130c72d3b17677f8a3798229a4bf7236295ea7d0b5ac8bb2fa9d81e53'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Clases excelentes. Sus clases son 0% aburridas y muy entretenidas. Le gusta que los estudiantes participen. Deja pocas tareas por la participación y es muy comprensivo. Volvería a matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '371dc7bd8e7fc5f405d377faa3c041374dc3978073f061c3e7ba57e8c6ffe282'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El mejor profe de la escuela de ciencias sociales, no deja tanto trabajo como otros profes que imparten el curso y se aprenden bastante, además da un clima de confianza con los estudiantes. 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'bd6fe0083ac289e61b6124121aa97510b7cf6e8094c3829ebba33280f9dfadf1'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Virtual'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'c4bd6fecb51d8dccf887752e669984483f4d6dd71f73f47066a39e2dfe9cc0c0'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Uno de los mejores profes que he tenido en el tec, siempre está dispuesto a ayudar en lo que sea. El profesor sabe mucho y tiene facilidad para transmitir el conocimiento. El curso es muy fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '1ade8926b9f6a217baf2c4f7ec5ae816f5ae2384439e17396e5db66381814d56'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Uno de los mejores profes del TEC en general , las clases son un poco aburridas tal vez por el tipo de materia pero califica justo , deja trabajos cortos y siempre que puede le ayuda . Su medio de comunicación es whatsaap y no importa el día pero siempre le contesta su duda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'c05950cb4423e65cc71b61b59551d3193afa23ee7d226ce90f715d336a9cc590'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El curso es fácil en general, la materia no es muy interesante pero solo yendo a clases se pasa. Deja pocos trabajos y cortos. El proyecto es grupal. Ayuda en todo lo posible.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'e225c3c1a89cbb8d49ae75c6b80453f15628d41cde0735243c65527aa458a3ec'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Da la clase de forma increíble, la hace muy interesante y entretenida. Es muy comprensivo con la entrega de trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'd7dc16385850804d1a5ef4e17c59838a23c223fa95fa1bfe8809e35e191790b5'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Es de los mejores profes que he tenido. Se preocupa por sus estudiantes, y trata de hacer la clase más entretenida (son temas muy aburridos).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'c95c0ec553130cab64446d1b243d3eec71a3f1fb336b2838a95542438cc47307'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El mejor profesor para este curso, comprende la carga académica que uno lleva en el Tec y hace que el curso sea lo más fácil posible sin dejar de aprender.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'f9d3b56d5d62ba170f61ca7af909f58fd2a5bdd2a94e9da886b0325e08fe179d'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El profe entiende muy bien lo que representa el curso para los demás, lo hace muy accesible, con disponibilidad de fechas y evaluaciones cómodas e interesantes para el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '409ba192ed7de7581678407964ebefbc9e6528da4f45edef99f735825a577d53'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor, interesado por los estudiantes. Se adaptó muy bien a las clases virtuales y muy comprensivo con los estudiantes, daba bastante tiempo para la entrega de trabajos. Siempre estaba dispuesto a ayudar y siempre que le hagan consultas está dispuesto a ayudar, lo recomiendo muchísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '4608232f175a38de5c63e2dadc845db6ff8e8a81570157ff3ae7245dbbabdcef'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El profe se esforzó y se acomodó muy bien a la virtualización. Se toma su tiempo para explicar los trabajos para que uno los haga bien (casi que dice lo qué hay que poner exactamente), para el ensayo y proyecto nos pidió un adelanto (no tenía valor) para poder sacarnos un 100. Da puntos de extras.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '9af16c4834237f9f146653d0a628df77a84d03ad1f7d156cb8775ee34f31d83e'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Es un buen profesor, las clase dura aprox. 1hr y 30min (sincrónica) sin trabajo asincrónico. Es gracioso y ayuda mucho al estudiante, flexible con entregas y los trabajos no son largos. Al final del semestre deja varias cosas pero no son largas. Es fácil con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'b3724bcb930eff817502968d0998baabe7df7370879844bb55a5c44b8f8a6dbb'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Gran profesor, respeta y entiende la cantidad de trabajo que un estudiante posee, por lo que es comprensivo y da bastante tiempo para entregas. Si puede matricular con el hágalo gran experiencia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0bf13a711af050a56070cfdb2c975defa33f7a307a19d0fc50a10f0d76e5494b'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, '100% recomendado, las clases son muy interesantes y entretenidas. El profe es demasiado crack, sabe demasiado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'd99e035baf1f6314c2cfba8beedd0d6685105fd4966d7fca2af21361b6a16f67'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Es el mejor profe que he tenido, se esfuerza por hacer la clase interesante y hacerte pensar, es muy entretenido el curso porque él tiene mucho conocimiento. Si necesitas ayuda él lo hace con mucho gusto. Los trabajos son un poco largos pero nada imposible.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '4a026a997521bf593882994d0cb4b41e79116d795abde8facf728b9b8b80ce08'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Se preocupa por los estudiantes, es chistoso. Participe en clase, debatir es alentado. Los trabajos toman su tiempo, pero no en exceso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '12ef2d5f4ac5823d0b6ea05a3d370c08f9aadbf5a940cc8dc88cce7826cee3d3'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El profe es súper pura vida. Si ud quiere pasar el curso fácil llévelo con él, si quiere aprender y participar, también llévelo con él. Es super comprensivo, chistoso y pura vida. Sus exámenes se responden con los comentarios de la clase y las lecturas son interesantes! Excelente profe!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Pocos exámenes']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '569e42a2569fa3115c6fbb775d66672920ce37439934147bd2b566cedfc6d2dc'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Sin duda si asiste va a reflexionar en clases y por favor PARTICIPE así se hace más entretenido. Haga de este curso un medio para pensar; salga de la burbuja TEC y debata su opinión! La información que uno lee es bastante interesante pese a que algunos textos son complejos pero los explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'db4647a9bcd3fa9470646da43262ddb28510505b2a16ece6b24fcda034312482'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'aae4683df03752a736e83c27f0f522f9c7e84df9e9b9f010f1c6ed1a7a0f1a1d'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Buen profe, para ser seminario, la clase fue entretenida, uno ve muchas películas, los trabajos son fáciles, y se aprende!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '13a08a1f2dfb8cd011eef2134e45219d533a4a89cc1379bba669b252ff509b6c'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Es súper relajado, es muy comprensivo. Los trabajos son sencillos, es un curso fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '5c71a89927fbfb232fdbd9f4ccbb94900cc3457faa2c244927deced9cdae729c'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Fue la Formación Humanística que más me gustó a pesar de no ser fan de la saga'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'b3b9ba8b9e9a69d83956b21c5dafddaf9856f63314d438721c235e20f94fb2b9'::TEXT, ARRAY[899]::BIGINT[]),
    (111::BIGINT, 'Es la mismísima reencarnación de Sigmund Freud con la voz de Walt Disney!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'de9896c58d50df0921f6d4d12cb542c56e251d75dbcb1039b2a0fb942fd71ba5'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Es excelente como profesor y como persona. Hace que el curso no se haga tan aburrido. Los exámenes y guía se hacen en parejas y con solo escribir algo medio coherente tiene un 100. Lo mejor son sus chistes sobre la liga'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, '25348e16849bcaf3dba656104d7b13c506a3d6480bfd49f785dc207a4c203d71'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Super buen profe, la materia es aburrida pero el trata de que participemos y que sea interesante, se pasa super fácil si usted hace las tareas y examenes que no llevan demasiado tiempo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'cd36897295eb8dd08080118ce98ad59446078a9b9137ba34e15f030c73143396'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El curso es aburrido pero el profe es excelente y hace la clase llevadera y divertida, los trabajos y exámenes se pueden hacer en parejas :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '3dd4612affd658fb00f00353b91cb4271274e9dddf4ab8af424afd12c6d67e17'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'No solo es un excelente profe, pero una excelente persona. Las clases son súper interesesantes y amenas. Deja pocos trabajos y los califica suave (se pueden hacer los trabajo en parejas). Es divertido y se nota que le encanta enseñar. Además, en mi caso nunca pasó lista.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'a8e22af528c60dc07eab693213f7ee2f78a68d610eb4d3434e843e1ea9f09d6b'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor, explica muy bien. Los trabajos que evalúa se pueden hacer en parejas y deja los exámenes para hacer en casa. Puede hacer una clase bastante entretenida e interesante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '89ae3f432d1990563487e9b9ddf53e74ff64fb8bc2c0509e23d6a6a818054b34'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor!, sin duda deberían existir mas profesores como él que hace de una materia de tres horas algo muy divertido y con gran participación. Evalúa lo necesario, pocas lecturas pero interesantes y es muy agradable asistir a sus clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '997ea5b4af8d74a3021fd9e5f9dba41b0de4bdb134fd27f1b098d72473e4d6d3'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Excelente profe, el curso no es tan bonito pero el profe hace las clases muy amenas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-08T00:00:00+00:00'::TIMESTAMPTZ, '00668f55a5cd47b7ec4f169bfa969a0b73523c7fd1f9378554bf96446e57c768'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor, es muy comprensivo y es súper buena nota! Asistencia obligatoria pero casi nunca pasa lista. :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-09-20T00:00:00+00:00'::TIMESTAMPTZ, 'aed9487f1636c1fad066837ad7cb50693e912460051c14f073ddfe1b65aa9c52'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El mejor profesor para este curso, sin lugar a duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, '50060c6be851db06bf2e31a9f16e300991ac30af450bacd10fe1e3f6892b4d4e'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Excelente profe. Hace que de un curso "aburrido" se puedan hacer clases entretenidas e interesantes donde se discuten las lecturas asignadas. Solo evalúa mediante quices, unas pocas guías, ensayos y el examen. El mejor para este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b7a6e067537a3d98d8c95b69b544cd83a98da561d3a74863182713ad19de622a'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Muy buen profe, hace de una materia aburrida una lección interesante. No pidió presentaciones, las clases eran de discusión basadas en las lecturas de la cátedra (hay resúmenes rondando entre los estudiantes, pero vale la pena leerlos si les gusta debatir, a él le encanta). Super buena nota!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ec031327524947e7509a4a8e028251d4e6a46cec3363824e213cf6f3c24d7b59'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'De los mejores profes que he tenido, hace que el curso se vuelva más liviano y entretenido. Además es flexible con las fechas de entrega de trabajos (que son pocos) y califica realmente suave, pero siempre intenta motivarlo a uno, cosa que es difícil en un profe del TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'd69b42694c2538020bd3ad6f5e5e5feba8fafb6530ceacf764771fd0c6dfa705'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Excelente profe, la clase es muy interesante y divertida, no deja muchos trabajos, además es muy flexible con las fechas de entrega.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '4f04fc1559d55d51e1800e5cc6583e30942cf35fd7b8b0f0d97105bfdf0d20dc'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Es muy vacilón y buena gente. Habla demasiado y da sueño pero qué se puede esperar de intro al bostezo? Es súper fácil pasar con él!!! Los trabajos que deja son demasiado fáciles, y no se necesita demasiado tiempo para hacerlos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '47b40ff335b2d0f212e16e4bf96f735cdb0a00aeaa278e4ec40ac33bc9dc8ce8'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor. Clases divertidas y para nada aburridas. Lecturas cortas, proyecto final fácil y corto. Muy flexible con las fechas de entrega de los análisis y trabajos sencillos que hay que hacer. Super recomendado, de lo mejor que tiene esta escuela.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e9f72b00f3285f1ef80983bf122757cbf984503b2cf74649ededa529a066be40'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'A veces sus clases son aburridas porque son casi monólogos. Deja resúmenes de las lecturas y avisa cuando hace quices. Es muy buena persona, se nota que le encanta lo que hace. Deja ensayos y análisis, pero o hace exámenes. MUY recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '053de7d76adfe468b99e98bdd80efea0798e005736afc7dd3d5cb3839cff9c68'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El profe es super pura vida, no hace el curso tan tedioso y se interesa por los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '5b637b20cd5c7f0c368ec2a549e6ac7b4c0885c2c503afc8a40a58a841c7fd90'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'De los mejores profes de Ciencias Sociales. Se ve que le apasiona lo que hace, muy cómico por su sarcasmo. Lecturas adecuadas para un curso de 3 créditos. Exposiciones fáciles, análisis de casos largos pero fáciles. Si ve que uno se esfuerza lo felicita y es flexible con las fechas. Recomendado!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, '6e74f847c62e90fd24635f1d6a11d89ff3cf83bd1afcafed1880ea5c8f4e5d78'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Es un buen profe, sus clases pueden ser aburridas o entretenidas, hay momentos de momentos. Normal al calificar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-04T00:00:00+00:00'::TIMESTAMPTZ, '898e88f392464c0b2cba393702cf19094ff6fa3b31dfa7f66d9de80258458de2'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Califica justo, muy cómico, muy accesible, de lo mejor que tiene la escuela. Es perfecto para llevar el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2018-05-23T00:00:00+00:00'::TIMESTAMPTZ, '55ebac0df47a4d7beeee736f3bb91abf0e8dbee8cc33a774487a788b2d216d4f'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Es él o nadie'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'bdd091ebe2ef4c43757607bdf5429dbaf95bdbdd7a9be5b8a0b33c9961e0351e'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Excelente profe, clase entretenida, se disfruta la materia y existe un ambiente de confianza en la clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '1b6d921cbb69603954486fb23e791203312509348d07fa3bceba30a6a5944d98'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'El mejor profe de todos, sus clases son muy divertidas y se aprende un montón.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-26T00:00:00+00:00'::TIMESTAMPTZ, '8c821d9a41134ce0b9901df60f7cd1f01d0dc1b29178bdb090845a6eb748f8da'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Creo que lo más importante de él es que lo entiende a uno como estudiante entonces deja nada más los trabajos necesarios y no se pone en mucha vara nunca.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'cf3ea8ea848ff24536bbb06e180c4a8a7d4e884f35bcbd1eda1e8d8a56736115'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Cómico, comprensible. Es el profe que menos deja trabajos, apenas lo necesario. De una con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f45d96b3953eacdf6454e04406792d4fc28dc10d5ac112efd4c245f96be68ba7'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Bastante fácil. Sin duda con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f8c293857cd50fb8547e7fb26f602b6b74be636aab71b86bac454389900a179f'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e32567b90f4413766b6e483f246ae13702fb5709de703ced4364698bae2c7d23'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'El mejor profesor de la escuela de Ciencias sociales. Divertido, relajado y se aprende muchisimo! Sumamente comprensivo y nada estricto'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6d20952d7ba355a04288346e54aeccbb5bfdfa1588f57ea296b4713112021f85'::TEXT, ARRAY[981]::BIGINT[]),
    (111::BIGINT, 'Con el SIN DUDA!! Facilisimo y discute todas las lecturas tanto que a la hora de hacer los exámenes (que son para la casa y en parejas) si uno tiene notas de lo que el dijo se vuelve sencillisimo! Las clases no las hace aburridas y lo recomiendo 100%!! Ayuda muchisimo si uno tiene cualquier duda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '5b59106d0f4aa4e08a9ecb0e552d9a3f930747e70fc3e80695acf18909c7b807'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Excelente profesor!! Hace las clases interesantes y es muy pura vida. Es bastante relajado respecto a las evaluaciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '72774ebaff774abf8dbaf3119613c176fdb0644138ee1a8f666f695269cc7ec3'::TEXT, ARRAY[980]::BIGINT[]),
    (111::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'bb2b0ad4de30ce59987a1547f06dd0f4d691e02567c0e79945f216f8fd5a3ff6'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Sin duda alguna es un excelente profesor!!!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-04-09T00:00:00+00:00'::TIMESTAMPTZ, '4ccb12885b21f5119a78dfdaf1db73bb2fd7ae3081b39292640cd0495f62b5ca'::TEXT, ARRAY[1004]::BIGINT[]),
    (111::BIGINT, 'Hace la clase interesante. Mientras no falte, es imposible quedarse'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'd6d25e97c1a228c45dea74faab0cacf879ddc872371e059f02b1b99f3a1c1ca3'::TEXT, ARRAY[559]::BIGINT[]),
    (111::BIGINT, 'Simplemente es un crack! hace las clases muy divertidas y ademas expresa mucho conocimiento, deja los trabajos que pide el curso, si haces los trabajos con interés automáticamente tienes 100, le gusta que participen en clase, si entregas los trabajos no hay forma de quedarse.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, '4b25e7e69f5f599aaa5d001c5adea01fcedd5b2e3167fb7715f462c7513f5383'::TEXT, ARRAY[980]::BIGINT[]),
